import { SmokeRing, type SmokeRingProps } from "@paper-design/shaders-react";
import { forwardRef, useCallback, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const NEUTRAL_COLORS = ["#c8c8d0"];

interface ShaderSmokeRingProps
  extends Omit<SmokeRingProps, "frame" | "ref"> {}

function ShaderSmokeRingBase({
  speed = 1,
  colorBack = "#12121a",
  colors = NEUTRAL_COLORS,
  radius = 0.25,
  thickness = 0.65,
  scale = 0.8,
  className,
  ...rest
}: ShaderSmokeRingProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const [handle] = useState(() => delayRender("shader-smoke-ring"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0 }}
    >
      <SmokeRing
        speed={0}
        frame={(frame / fps) * speed * 1000}
        colorBack={colorBack}
        colors={colors}
        radius={radius}
        thickness={thickness}
        scale={scale}
        fit="cover"
        width={width}
        height={height}
        {...rest}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  radius: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.25,
    description: "Radius",
    hiddenFromList: false,
  },
  thickness: {
    type: "number",
    min: 0.1,
    max: 1.5,
    step: 0.05,
    default: 0.65,
    description: "Thickness",
    hiddenFromList: false,
  },
  scale: {
    type: "number",
    min: 0.3,
    max: 2,
    step: 0.05,
    default: 0.8,
    description: "Scale",
    hiddenFromList: false,
  },
  colorBack: {
    type: "color",
    default: "#12121a",
    description: "Background",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["speed","radius","thickness","scale","colorBack"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  speed: 1,
  radius: 0.25,
  thickness: 0.65,
  scale: 0.8,
  colorBack: "#12121a",
};

type ShaderSmokeRingElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShaderSmokeRingBase>;

const ShaderSmokeRingInner = forwardRef<
  HTMLDivElement,
  ShaderSmokeRingElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShaderSmokeRing>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShaderSmokeRingBase
          {...(componentProps as unknown as ComponentProps<typeof ShaderSmokeRingBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShaderSmokeRing = Interactive.withSchema({
  Component: ShaderSmokeRingInner,
  componentName: "<ShaderSmokeRing>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
